const CACHE='handclub-beta-v8-training';
const ASSETS=['./','./index.html','./style.css','./core.js','./demo.js','./app.js','./config.js','./cloud.js','./family.js','./domain.js','./practical.css','./notifications.js','./help.js','./help.css','./ui.css','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png','./fonts/fonts.css','./fonts/bricolage-grotesque-normal.woff2','./fonts/fraunces-normal.woff2','./fonts/fraunces-italic.woff2'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)));self.skipWaiting();});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('handclub-beta-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request,{cache:'no-cache'}).then(response=>{if(response.ok&&ASSETS.some(asset=>new URL(asset,self.location).href===event.request.url)){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(cached=>cached||Response.error())));});
self.addEventListener('push',event=>{let payload={title:'Lumo',body:'Une information du club vous attend.',eventId:''};try{Object.assign(payload,event.data.json());}catch{}event.waitUntil(self.registration.showNotification(String(payload.title).slice(0,100),{body:String(payload.body).slice(0,300),icon:'./icon-192.png',badge:'./icon-192.png',data:{eventId:payload.eventId,notificationId:payload.notificationId},tag:payload.tag||'lumo'}));});
self.addEventListener('notificationclick',event=>{event.notification.close();const url=new URL('./',self.location).href+(event.notification.data?.eventId?'#event='+encodeURIComponent(event.notification.data.eventId):'');event.waitUntil(self.clients.matchAll({type:'window',includeUncontrolled:true}).then(async windows=>{const window=windows.find(client=>client.url.startsWith(self.registration.scope));if(window){await window.navigate(url);return window.focus();}return self.clients.openWindow(url);}));});
